fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "AUTO"
    val seconds = exposureTimeNs / 1_000_000_000.0
    val fraction = 1.0 / seconds
    if (fraction >= 1) {
        val rounded = fraction.roundToInt()
        return "1/${rounded}s"
    }
    return if (seconds >= 1) {
        "${seconds.toInt()}s"
    } else {
        "${String.format("%.1f", seconds).removeSuffix("0").removeSuffix(".")}" + "s"
    }
}

